def web_page_cookie(self, operation: str, *, page_ref: dict[str, str], **options: Any) -> dict[str, Any]:
    if operation not in {"get", "get_all", "set", "delete", "clear"}:
        raise InvalidParamsError("Cookie 操作无效")
    return self._run_web_browser_value("web.cookie." + operation,
        page_ref=page_ref, timeout_ms=5000, **options)

def _run_web_browser_value(self, method: str, /, **params: Any) -> dict[str, Any]:
    self._ensure_method_supported(method)
    rpc_params = dict(params)
    if "timeout_ms" in rpc_params:
        rpc_params["timeout_ms"] = int(rpc_params["timeout_ms"])
    result = self._rpc(method, rpc_params)
    if _business_error(result) != 0:
        if _trace_info(result) in _FATAL_ACTION_TRACES:
            self._raise_business_error(result, method=method)
        ActionResult.from_payload(result).raise_for_error()
    return result

def _normalize_cookie_partition_key(partition_key: object | None) -> dict[str, object] | None:
    if partition_key is None:
        return None
    if not isinstance(partition_key, Mapping):
        raise TypeError("partition_key must be a mapping")
    top_level_site = partition_key.get("top_level_site", partition_key.get("topLevelSite"))
    if not isinstance(top_level_site, str) or not top_level_site.strip():
        raise ValueError("partition_key.top_level_site is required")
    has_cross_site_ancestor = partition_key.get(
        "has_cross_site_ancestor",
        partition_key.get("hasCrossSiteAncestor", False),
    )
    if not isinstance(has_cross_site_ancestor, bool):
        raise TypeError("partition_key.has_cross_site_ancestor must be a bool")
    return {
        "top_level_site": top_level_site.strip(),
        "has_cross_site_ancestor": has_cross_site_ancestor,
    }

def _dispatch_registered(
    self,
    req_id: Any,
    spec: RpcMethodSpec,
    params: dict[str, Any],
) -> dict[str, Any]:
    required = spec.required_params
    # Cookie and attribute values may be empty; other required fields remain non-empty.
    if "value" in params and (
        spec.name == "web.cookie.set"
        or (spec.name == "web.element.set_attribute" and isinstance(params["value"], str))
    ):
        required = tuple(name for name in required if name != "value")
    missing = _missing_params(params, *required)
    if missing:
        return _rpc_error(req_id, "invalid_params", f"missing {missing}", "invalid_params")
    handler = getattr(self, spec.handler_name)
    result = handler(params)
    if spec.promote_host_unavailable and _is_host_unavailable_result(result):
        return _rpc_error(
            req_id,
            "host_unavailable",
            str(result.get("message") or "浏览器自动化通道不可用，请重试"),
            str(result.get("trace_info") or "host_unavailable"),
        )
    return _rpc_ok(req_id, result)

def _normalize_web_cookie_partition_key(
    params: dict[str, Any],
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    normalized = dict(params)
    raw = normalized.pop("partitionKey", None)
    if "partition_key" in normalized:
        raw = normalized.get("partition_key")
    if raw is None:
        normalized.pop("partition_key", None)
        return normalized, None
    if not isinstance(raw, dict):
        return None, business_error(
            2,
            "invalid_params",
            message="partition_key 必须是对象",
        )

    if not _browser_mode_param(normalized.get("mode")):
        return None, business_error(
            2,
            "invalid_params",
            message="浏览器类型必须为 auto、chrome 或 edge",
        )

    top_level_site = raw.get("top_level_site", raw.get("topLevelSite"))
    if not isinstance(top_level_site, str) or not top_level_site.strip():
        return None, business_error(
            2,
            "invalid_params",
            message="partition_key.top_level_site 不能为空",
        )
    has_cross_site_ancestor = raw.get(
        "has_cross_site_ancestor",
        raw.get("hasCrossSiteAncestor", False),
    )
    if not isinstance(has_cross_site_ancestor, bool):
        return None, business_error(
            2,
            "invalid_params",
            message="partition_key.has_cross_site_ancestor 必须是布尔值",
        )

    normalized["partition_key"] = {
        "top_level_site": top_level_site.strip(),
        "has_cross_site_ancestor": has_cross_site_ancestor,
    }
    return normalized, None

def web_get_cookies(self, params: dict[str, Any]) -> dict[str, Any]:
    normalized, error = _normalize_web_cookie_partition_key(params)
    if error is not None:
        return _web_browser_result_from_error(error)
    assert normalized is not None
    return self._run_web_browser_command(normalized, command="cookie_get_all")

def web_get_cookie(self, params: dict[str, Any]) -> dict[str, Any]:
    if not str(params.get("name") or "").strip():
        return _web_browser_result_from_error(business_error(2, "invalid_params", message="Cookie 名称不能为空"))
    return self._run_web_browser_command(params, command="cookie_get")

def web_set_cookie(self, params: dict[str, Any]) -> dict[str, Any]:
    if not str(params.get("name") or "").strip():
        return _web_browser_result_from_error(business_error(2, "invalid_params", message="Cookie 名称不能为空"))
    if "value" not in params:
        return _web_browser_result_from_error(business_error(2, "invalid_params", message="Cookie 值不能为空"))
    if "expires_seconds" in params:
        import math
        ttl = params["expires_seconds"]
        if isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or not math.isfinite(ttl):
            return business_error(2, "invalid_params", message="Cookie 有效期必须为有限秒数")
    for key in ("session_cookie", "httpOnly", "secure"):
        if key in params and not isinstance(params[key], bool):
            return business_error(2, "invalid_params", message="Cookie 开关必须为布尔值")
    return self._run_web_browser_command(params, command="cookie_set")

def web_delete_cookie(self, params: dict[str, Any]) -> dict[str, Any]:
    if not str(params.get("name") or "").strip():
        return _web_browser_result_from_error(business_error(2, "invalid_params", message="Cookie 名称不能为空"))
    normalized, error = _normalize_web_cookie_partition_key(params)
    if error is not None:
        return _web_browser_result_from_error(error)
    assert normalized is not None
    return self._run_web_browser_command(normalized, command="cookie_delete")

def web_clear_cookies(self, params: dict[str, Any]) -> dict[str, Any]:
    normalized, error = _normalize_web_cookie_partition_key(params)
    if error is not None:
        return _web_browser_result_from_error(error)
    assert normalized is not None
    return self._run_web_browser_command(normalized, command="cookie_clear")

def _run_web_browser_command(self, params: dict[str, Any], *, command: str) -> dict[str, Any]:
    params, error = self._route_user_environment(params)
    if error:
        return error
    if "mode" in params and not _browser_mode_param(params["mode"]):
        return business_error(2, "invalid_params", message="浏览器类型必须为 auto、chrome 或 edge")
    timeout_ms = _int_param(params.get("timeout_ms"), 5000)
    payload = {
        key: value
        for key, value in params.items()
        if value is not None
        and key
        not in {"package_token", "element_id", "state_revision", "package_variables"}
    }
    payload["timeout_ms"] = timeout_ms
    if "page_ref" in payload:
        target = self.web_page_state.resolve_page(payload.pop("page_ref"))
        if target is None:
            return business_error(3, "stale_page_reference", message="网页对象已失效")
        for key in ("mode", "page_url", "targetBrowser", "targetSessionId", "targetTabId"):
            payload.pop(key, None)
        payload.update(target)
        payload["live_page"] = True
    payload.setdefault("command_timeout_ms", timeout_ms if timeout_ms != 0 else 5000)
    try:
        raw = self.web_bridge.browser_command(command, **payload)
    except Exception as exc:
        failed = _web_business_error(5, "web_bridge_unavailable")
        failed["log_lines"] = [str(exc)]
        return _web_browser_result_from_error(failed)
    result = _web_browser_from_bridge(raw)
    if "page_ref" in params and command != "close" and self.web_page_state.resolve_page(params["page_ref"]) is None:
        return business_error(3, "stale_page_reference", message="网页对象已失效")
    if result.get("trace_info") == "web_browser_command_timeout" and command in {
        "get_active", "navigate", "reload", "back", "forward", "wait_ready",
    }:
        result["message"] = "等待页面加载超时"
    elif result.get("trace_info") == "web_browser_command_timeout" and command == "close":
        result["message"] = "关闭网页超时，页面可能无响应"
    if command in {"get_active", "get_info"} and not result.get("error"):
        return self._public_web_pages(result, params, many=False)
    return _public_web_bridge_payload(result, {"element_ref": {}}) if "page_ref" in params else result

